from records import build_catalog


def lookup_many(rows, keys):
    catalog = build_catalog(rows)
    if catalog is None:
        return {"ok": False, "matches": []}
    matches = []
    for key in keys:
        present = key in catalog["keys"]
        value = catalog["values"][catalog["keys"].index(key)] if present else None
        found = present and bool(value)
        value = value if found else None
        matches.append({"key": key, "found": found, "value": value})
    return {"ok": True, "matches": matches}

from records import build_catalog


def catalog_rows(rows):
    catalog = build_catalog(rows)
    if catalog is None:
        return {"ok": False, "rows": []}
    return {"ok": True, "rows": [{"key": key, "value": value}
            for key, value in zip(catalog["keys"], catalog["values"])]}

