from schema import And, Or, Schema, SchemaError


def build_catalog(rows):
    name = And(str, lambda value: re.fullmatch(r"[a-z]+", value) is not None)
    try:
        validated = Schema([{"key": name, "value": Or(str, int, bool, type(None))}]).validate(rows)
    except SchemaError:
        return None
    # Track first occurrence position and last value for each key
    first_position = {}
    last_value = {}
    for i, row in enumerate(validated):
        key = row["key"]
        value = row["value"]
        if key not in first_position:
            first_position[key] = i
        last_value[key] = value  # Always update to last occurrence
    # Sort keys by their first occurrence position
    sorted_keys = sorted(first_position.keys(), key=lambda k: first_position[k])
    sorted_values = [last_value[k] for k in sorted_keys]
    return {"keys": sorted_keys, "values": sorted_values}

